{"hypotheses": [
  {
    "name": "Hypothesis 1",
    "mechanism": "A combination of firm size and momentum can enhance risk-adjusted returns due to larger firms' better resources and institutional support, and the persistence of trends in stock prices.",
    "expression": { 
        "terms": [
            {"weight": 0.5, "primitive": "Size"},
            {"weight": 0.5, "primitive": "Mom12m"}
        ],
        "regime": "VIX_BELOW_TRAILING_MEDIAN", 
        "vol_target": true
    },
    "auxiliary_predictions": [
        {"type": "size_segment", "segment": "mega", "direction": "stronger"},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
        {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hypothesis 2",
    "mechanism": "The combination of high book-to-market ratios and low earnings-to-price ratios can provide superior returns due to mispricing of value stocks and market inefficacies.",
    "expression": { 
        "terms": [
            {"weight": 0.5, "primitive": "BM"},
            {"weight": -0.5, "primitive": "EP"}
        ],
        "regime": "TERM_SPREAD_POSITIVE",
